// Adapter: the rule below is the same JavaScript as the recipe's n8n build.
// $('Step name') answers from this step's inputs: each is that step's output in this scenario.
const SOURCES = {"Config": "in0_Config", "Read open drafts": "in1_Readopendrafts"};
const LISTS = [];
const EXECUTED = [];
const DATA = {};
for (const [node, key] of Object.entries(SOURCES)) {
  const raw = input[key];
  let v = raw;
  if (typeof raw === 'string') { try { v = JSON.parse(raw); } catch (e) { v = raw; } }
  DATA[node] = LISTS.includes(node) ? (v || []).map(i => (i && i.json !== undefined ? i : { json: i })) : [{ json: v }];
}
const $ = (node) => {
  const ran = node in DATA || EXECUTED.includes(node);
  const list = () => { if (!(node in DATA)) throw new Error(`step ${node} has no data in this scenario`); return DATA[node]; };
  return { isExecuted: ran, first: () => list()[0], last: () => list()[list().length - 1], all: () => list(),
           get item() { return list()[0]; } };
};
const INPUT = "Read open drafts";
const $input = { all: () => $(INPUT).all(), first: () => $(INPUT).first(), last: () => $(INPUT).last(), get item() { return $(INPUT).first(); } };
const $execution = { id: input.run_id };
const BODIES = (out) => ({"week_q": encodeURIComponent(out.week), "failed_body": JSON.stringify({ recipe: 'R12.2', item: 'four', reason: 'write failed', detail: 'A verification or publication write failed; check the draft and pre-read', owner: $('Config').first().json.verifier }), "patch_body": JSON.stringify(out.patch), "ask_body": JSON.stringify({ to: $('Config').first().json.backup_verifier, subject: 'Verify the weekly narrative by 16:45', text: 'Week ' + out.week + ': the narrative is not yet verified.' })});
const one = (r) => (Array.isArray(r) ? r : [r]).filter(Boolean).map(i => (i.json !== undefined ? i.json : i));
const $json = INPUT && INPUT in DATA ? $input.first().json : {};
const __rule = () => {
// Step 13 at 16:00: close the week to new drafts (step 14); a draft not yet verified goes to the backup verifier.
const drafts = ($('Read open drafts').first().json.items || []).filter(d => d.closed !== true);
return drafts.map(d => ({ json: { week: d.week, notify: d.stage === 'to verify',
  patch: { closed: true, stage: d.stage === 'to verify' ? 'backup' : d.stage } } }));
};
return { items: one(__rule()).map(o => Object.assign({}, o, BODIES(o))) };
